#!/usr/bin/env bash
# Repo-level drift check for the shared contract goldens.
#
# A golden is a JSON file generated by the code that owns the contract (never
# written by hand), committed once, and read by every consumer's own tests. Two
# things can silently break that: someone edits the golden without the owner's
# code producing it, or a consumer's vendored copy stops matching the original.
# This script closes both:
#
#   * every golden listed in GOLDENS must hash to the digest pinned next to it,
#     so changing a contract is a deliberate second step (regenerate with the
#     owner's generator, then update the pin here, in the same change);
#   * every vendored copy listed in VENDORED must be byte-identical to its
#     golden, so a consumer is tested against what the owner really emits.
#
# A missing file is a failure, never a skip: a listed golden or copy that is not
# there means the check it stands for is not running. Goldens are LF files
# (.gitattributes pins *.json to eol=lf), hashed byte for byte.
#
# Two goldens are the exception to "generated by the owner's code": the ZDR posture
# matrix and the connection capability contract are authored specifications that every
# plane's real function is tested against. They are held to a stricter loader instead
# (scripts/tests/zdr-contract-schema.mjs: no unknown field, no row without a code, only
# Z-05a catalogue codes, no row that breaks a safety property, the two files agree),
# which this script runs on every check.
#
# CONSUMERS says who must vendor which golden. A consumer that has not vendored its
# copy yet is reported as "pending"; under REQUIRE_CONTRACT (set it in any job that
# runs from a full checkout and expects the build to be complete) a pending consumer
# FAILS, so a plane cannot be tested against nothing and pass by not looking.
#
# Adding a golden: append "<repo-relative path>|<sha256>" to GOLDENS. A pin file
# "<path>.sha256" beside it, if there is one, must carry the same digest.
# Vendoring a copy: append "<repo-relative copy>|<repo-relative golden>" to
# VENDORED, in the change that adds the copy (and one row for its .sha256 pin).
#
#   scripts/tests/zdr-contract-sync.test.sh              check the repository
#   scripts/tests/zdr-contract-sync.test.sh --self-test  prove the check fails on a tampered golden
#   REQUIRE_CONTRACT=1 scripts/tests/zdr-contract-sync.test.sh   also fail on a consumer that has not vendored yet
set -Eeuo pipefail

SELF="${BASH_SOURCE[0]}"
SCRIPT_DIR="$(cd "$(dirname "$SELF")" && pwd)"
# CONTRACT_SYNC_ROOT lets the self-test point the same checks at a scratch tree.
ROOT="${CONTRACT_SYNC_ROOT:-$(cd "$SCRIPT_DIR/../.." && pwd)}"

# "<repo-relative path>|<sha256>"
GOLDENS=(
