  # the wire (code, x-mp-provider-error kind, retry timing). Generated by
  #   MP_UPDATE_GOLDEN=1 cargo test -p inference-core --lib status_contract
  # in "apps/Model Plane/rust". Consumed by the Data Plane inference client.
  "apps/Model Plane/api/contracts/infer-statuses.json|64c913fd2e342d3ce793cb55e03cd5c192ef867aca39df3eb85c4b5eab9084f4"

  # CR-T5: what Auth Core's real mint answers a Data Plane worker (embedding-engine,
  # graph-index) that asks for an aud=inference-core service token: the real registry
  # rows, the real tokens for every retention posture (persistent, zdr, tenant with
  # both claim values) and the real 503/403 bodies. Written by the real controller
  # (signature segments replaced by a fixed marker, so regeneration is byte-identical)
  # with
  #   UPDATE_CONTRACT_GOLDEN=1 npx jest inference-service-token.contract
  # in "apps/Control Plane/auth-core", which also vendors it, with its .sha256 pin,
  # into the Data Plane inference client. Regenerate it whenever the two principal
  # rows in config/plane-service-principals.json change.
  "apps/Control Plane/auth-core/src/auth/fixtures/inference-service-tokens.golden.json|afa8844a55345f3c2222cfb45cb6c3a73acd026e600a5941205411a1cfc3411b"

  # Auth Core -> org-core retention-posture wire contract (also the directory
  # check's request). Written by Auth Core's real resolver with
