  # in "apps/Control Plane/auth-core", which writes this copy, org-core's, and the
  # .sha256 pin beside each. Consumed by org-core's Go contract test.
  "apps/Control Plane/auth-core/src/auth/fixtures/auth-core-org-core-retention-posture.contract.json|bf8353bea90874fa0c10bd25ec2e1716b8de24bcb64ad638c8aad5f4b8ef3f81"

  # The claims of aud=quarry tokens as Auth Core really mints them. Written with
  #   UPDATE_GOLDENS=1 npx jest src/auth/quarry-token-zdr-claims.golden.spec.ts
  # in "apps/Control Plane/auth-core", which also vendors it into Quarry.
  "apps/Control Plane/auth-core/src/auth/fixtures/quarry-token-claims.golden.json|ec0ae10c182493fd61f369b7a63ee6dd3156039e5230918933e5413af8beeffa"

  # What Auth Core emits to the Data Plane for a service caller, and what it
  # answers when the Data Plane asks whether that caller is a member. Written with
  #   UPDATE_CONTRACT_GOLDEN=1 npx jest data-plane-service-principal.contract
  # in "apps/Control Plane/auth-core", which also vendors both into the retrieval
  # engine's tests.
  "apps/Control Plane/auth-core/src/auth/fixtures/data-plane-authorization-decision.golden.json|120d6ede13d0eb7b8743cc974a8f56091ea9e8c6b97e41b3b49f23da76b896a4"
  "apps/Control Plane/auth-core/src/auth/fixtures/data-plane-service-token-claims.golden.json|d73ff5d37987631eebcd4ee32b1298eef8feb51a15aa9c600c6588db16703982"

  # What session-core really publishes to audit-core for a governed tool action.
  # Written by session-core's builder test with
  #   UPDATE_AUDIT_CORE_FIXTURES=1 cargo test ... audit_core_wire_fixtures
  # in "apps/Model Plane/rust"; vendored into audit-core for its Go tests.
  "apps/Model Plane/rust/services/session-core/tests/fixtures/audit-core-wire/tool_action_final.json|2898d05fe596442bcf2579a01f10d797c379f894995d4f3668cabcd0290c0db5"
  "apps/Model Plane/rust/services/session-core/tests/fixtures/audit-core-wire/tool_action_reserved.json|4cfba644b5d8320205215dcbbd176cf53b54cf0aafb09dbb8b161e547838e14e"

  # Z-10: the retention-posture matrix and the connection capability contract.
  # AUTHORED data, not generated: the specification each plane's own real function
  # (Auth Core TS, mp-contracts Rust, the BFF Rust, integration-corev2 Go, inference-core)
  # is tested against. To change one: edit it, run
  #   node scripts/tests/zdr-contract-schema.mjs
  # (and the node --test file beside it), refresh the .sha256 pin beside it, update the
  # digest here, then re-vendor every copy listed in VENDORED and refresh its pin. See
  # "apps/Model Plane/api/contracts/README.md".
  "apps/Model Plane/api/contracts/zdr-posture-matrix.json|a6ff6879c7ee55e17688ee6eaf81ca2119cfa05721cc476719b3a3c09c8f4e1a"
  "apps/Model Plane/api/contracts/connection-zdr-capabilities.json|a5f4abd31520dcaed2681fdb464316bd70fdaa409e398a4372b1fcc262cac3e3"

  # QB-T02: every Auth Core service-token request quarry-edge makes. AUTHORED data owned
  # by Quarry, not generated: the Rust loader, the source scan and the wire tests in
  # "apps/Ingestion Plane/Quarry-v2/crates/quarry-runtime" read it as it is. To change a
  # row: edit it, refresh the .sha256 pin beside it (the Rust tests in
  # src/token_request_contract.rs compare it), update the digest here, then re-vendor
  # every copy listed in VENDORED (Auth Core's, CR-T17) and refresh its pin.
  "apps/Ingestion Plane/Quarry-v2/crates/quarry-runtime/contracts/cross-plane-token-requests.json|0849784e418ef475b18f39a58850a0e06b2a0973032d2c2a60fa80908ef30359"
)

# "<repo-relative copy>|<repo-relative golden>"
# Each consuming tree holds its own copy, so its tests read nothing outside it.
# The .sha256 pins that sit beside a copy are compared too: a pin that drifts from
# the canonical one would let a stale copy pass its own pin test.
VENDORED=(
  # org-core's Go contract test (internal/http/retention_posture_contract_test.go).
  "apps/Control Plane/org-core/internal/http/testdata/auth-core-org-core-retention-posture.contract.json|apps/Control Plane/auth-core/src/auth/fixtures/auth-core-org-core-retention-posture.contract.json"
  "apps/Control Plane/org-core/internal/http/testdata/auth-core-org-core-retention-posture.contract.json.sha256|apps/Control Plane/auth-core/src/auth/fixtures/auth-core-org-core-retention-posture.contract.json.sha256"

  # Quarry's token-claims contract test (crates/quarry-edge/tests/zdr_claim_floor.rs).
  "apps/Ingestion Plane/Quarry-v2/crates/quarry-edge/tests/fixtures/auth-core/quarry-token-claims.golden.json|apps/Control Plane/auth-core/src/auth/fixtures/quarry-token-claims.golden.json"
  "apps/Ingestion Plane/Quarry-v2/crates/quarry-edge/tests/fixtures/auth-core/quarry-token-claims.golden.sha256|apps/Control Plane/auth-core/src/auth/fixtures/quarry-token-claims.golden.sha256"

  # The retrieval engine's service-principal tests (tests/service_principal_auth.rs).
  "apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/auth-core/data-plane-authorization-decision.golden.json|apps/Control Plane/auth-core/src/auth/fixtures/data-plane-authorization-decision.golden.json"
  "apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/auth-core/data-plane-authorization-decision.golden.json.sha256|apps/Control Plane/auth-core/src/auth/fixtures/data-plane-authorization-decision.golden.json.sha256"
  "apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/auth-core/data-plane-service-token-claims.golden.json|apps/Control Plane/auth-core/src/auth/fixtures/data-plane-service-token-claims.golden.json"
  "apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/auth-core/data-plane-service-token-claims.golden.json.sha256|apps/Control Plane/auth-core/src/auth/fixtures/data-plane-service-token-claims.golden.json.sha256"

  # audit-core's session-core wire tests (internal/subscriber, internal/store).
  "apps/Control Plane/audit-core/internal/testdata/session-core-wire/tool_action_final.json|apps/Model Plane/rust/services/session-core/tests/fixtures/audit-core-wire/tool_action_final.json"
  "apps/Control Plane/audit-core/internal/testdata/session-core-wire/tool_action_reserved.json|apps/Model Plane/rust/services/session-core/tests/fixtures/audit-core-wire/tool_action_reserved.json"

  # inference-core's cross-check of the capability contract against the real provider
  # capabilities (tests/connection_zdr_capabilities_contract.rs).
  "apps/Model Plane/rust/services/inference-core/tests/fixtures/contracts/connection-zdr-capabilities.json|apps/Model Plane/api/contracts/connection-zdr-capabilities.json"
  "apps/Model Plane/rust/services/inference-core/tests/fixtures/contracts/connection-zdr-capabilities.json.sha256|apps/Model Plane/api/contracts/connection-zdr-capabilities.json.sha256"

  # The Data Plane inference client (CR-T5): its token contract and real-policy tests
  # (tests/token_contract.rs, tests/real_policy.rs) replay Auth Core's real mint, and its
  # status decoder test (tests/status_contract.rs) decodes every case inference-core emits.
  # infer-statuses.json has no .sha256 beside it: its digest is pinned in GOLDENS above,
  # and the client's own pin (tests/fixtures/inference-core/*.sha256) is checked by the
  # client's tests against its copy.
  "apps/Data Plane v2/services/inference-client-rs/tests/fixtures/auth-core/inference-service-tokens.golden.json|apps/Control Plane/auth-core/src/auth/fixtures/inference-service-tokens.golden.json"
  "apps/Data Plane v2/services/inference-client-rs/tests/fixtures/auth-core/inference-service-tokens.golden.json.sha256|apps/Control Plane/auth-core/src/auth/fixtures/inference-service-tokens.golden.json.sha256"
  "apps/Data Plane v2/services/inference-client-rs/tests/fixtures/inference-core/infer-statuses.json|apps/Model Plane/api/contracts/infer-statuses.json"

  # The Data Plane contextualizer (CR-T7), which sits on that client. Its outcome table is
