  # engine tests replay Auth Core's real mint through the real client
  # (src/provider/contextualize/tests.rs). Same files, same pins, its own tree.
  "apps/Data Plane v2/services/embedding-engine-rs/tests/fixtures/contracts/infer-statuses.json|apps/Model Plane/api/contracts/infer-statuses.json"
  "apps/Data Plane v2/services/embedding-engine-rs/tests/fixtures/contracts/inference-service-tokens.golden.json|apps/Control Plane/auth-core/src/auth/fixtures/inference-service-tokens.golden.json"
  "apps/Data Plane v2/services/embedding-engine-rs/tests/fixtures/contracts/inference-service-tokens.golden.json.sha256|apps/Control Plane/auth-core/src/auth/fixtures/inference-service-tokens.golden.json.sha256"

  # integration-corev2's capability assessor (internal/zdr, go:embed). The embedded copy is what the
